mapper.select:
select a.agent_id as agentId, a.agent_name as agentName, a.status, a.call_status as callStatus, a.login_time as loginTime, a.logout_time as logoutTime, timestampdiff(minute, a.login_time, coalesce(a.logout_time, now())) as signedInMinutes, ifnull(cr.inboundCalls, 0) as inboundCalls, ifnull(cr.talkDuration, 0) as talkDuration, ifnull(cr.avgTalkDuration, 0) as avgTalkDuration, ifnull(dl.outboundCalls, 0) as outboundCalls, ifnull(tr.transferredOut, 0) as transferredOut, ifnull(ass.aiAssistCount, 0) as aiAssistCount, ifnull(ob.avgSatisfaction, 0) as avgSatisfaction from ai_call_agent_status a left join ( select agent_id, count(*) as inboundCalls, ifnull(sum(duration), 0) as talkDuration, ifnull(round(avg(duration), 0), 0) as avgTalkDuration from ai_call_record
and call_time >= #{beginTime} and call_time < #{endTime}
group by agent_id ) cr on cr.agent_id = a.agent_id left join ( select agent_id, count(*) as outboundCalls from ai_call_dial_log
and dial_time >= #{beginTime} and dial_time < #{endTime}
group by agent_id ) dl on dl.agent_id = a.agent_id left join ( select from_agent_id as agent_id, count(*) as transferredOut from ai_call_transfer
and transfer_time >= #{beginTime} and transfer_time < #{endTime}
group by from_agent_id ) tr on tr.agent_id = a.agent_id left join ( select agent_id, count(*) as aiAssistCount from ai_ai_call_session
and start_time >= #{beginTime} and start_time < #{endTime}
group by agent_id ) ass on ass.agent_id = a.agent_id left join ( select agent_id, round(avg(case when satisfaction = '1' then 100 when satisfaction = '2' then 80 when satisfaction = '3' then 60 when satisfaction = '4' then 20 else null end), 0) as avgSatisfaction from ai_outbound_result
and start_time >= #{beginTime} and start_time < #{endTime}
group by agent_id ) ob on ob.agent_id = a.agent_id
and a.agent_name like concat('%', #{agentName}, '%')
order by inboundCalls desc, a.agent_id asc
